    19	// StatsFetcher has two functions for autopilot. First, lets us fetch all the
    20	// stats in parallel so we are taking a sample as close to the same time as
    21	// possible, since we are comparing time-sensitive info for the health check.
    22	// Second, it bounds the time so that one slow RPC can't hold up the health
    23	// check loop; as a side effect of how it implements this, it also limits to
    24	// a single in-flight RPC to any given server, so goroutines don't accumulate
    25	// as we run the health check fairly frequently.
    26	type StatsFetcher struct {
    27		logger       log.Logger
    28		pool         *pool.ConnPool
    29		region       string
    30		localID      raft.ServerID
    31		localServer  *Server
    32		inflight     map[raft.ServerID]struct{}
    33		inflightLock sync.Mutex
    34	}
    35	
    36	// NewStatsFetcher returns a stats fetcher.
    37	func NewStatsFetcher(logger log.Logger, pool *pool.ConnPool, region string) *StatsFetcher {
    38		return &StatsFetcher{
    39			logger:   logger.Named("stats_fetcher"),
    40			pool:     pool,
    41			region:   region,
    42			inflight: make(map[raft.ServerID]struct{}),
    43		}
    44	}
    45	
    46	// SetLocalServer sets the local server instance, enabling direct in-mem RPC
    47	// calls for the local server instead of going through the network pool.
    48	func (f *StatsFetcher) SetLocalServer(srv *Server) {
    49		f.localServer = srv
    50		f.localID = raft.ServerID(srv.config.NodeID)
    51	}
    52	
    53	// fetch does the RPC to fetch the server stats from a single server. We don't
    54	// cancel this when the context is canceled because we only want one in-flight
    55	// RPC to each server, so we let it finish and then clean up the in-flight
    56	// tracking.
    57	func (f *StatsFetcher) fetch(server *autopilot.Server, replyCh chan *autopilot.ServerStats) {
    58		var args structs.GenericRequest
    59		var reply structs.RaftStats
    60	
    61		// defer some cleanup to notify everything else that the fetching is no longer occurring
    62		// this is easier than trying to make the conditionals line up just right.
    63		defer func() {
    64			f.inflightLock.Lock()
    65			delete(f.inflight, server.ID)
    66			f.inflightLock.Unlock()
    67		}()
    68	
    69		// if this is a local server and we have a reference to it, don't go over
    70		// the network
    71		if f.localServer != nil && server.ID == f.localID {
    72			statusEndpoint := NewStatusEndpoint(f.localServer, nil)
    73			err := statusEndpoint.RaftStats(&args, &reply)
    74			if err != nil {
    75				f.logger.Warn("error getting server health", "server", server.Name, "error", err)
    76				return
    77			}
    78			replyCh <- reply.ToAutopilotServerStats()
    79			return
    80		}
    81	
    82		addr, err := net.ResolveTCPAddr("tcp", string(server.Address))
    83		if err != nil {
    84			f.logger.Warn("error resolving TCP address for server",
    85				"address", server.Address,
    86				"error", err)
    87			return
    88		}
    89	
    90		err = f.pool.RPC(f.region, addr, "Status.RaftStats", &args, &reply)
    91		if err != nil {
    92			f.logger.Warn("error getting server health", "server", server.Name, "error", err)
    93			return
    94		}
    95	
    96		replyCh <- reply.ToAutopilotServerStats()
    97	}
