1942	// setupWorkersLocked directly manipulates the server.config, so it is not safe to
1943	// call concurrently. Use setupWorkers() or call this with server.workerLock set.
1944	func (s *Server) setupWorkersLocked(ctx context.Context, poolArgs SchedulerWorkerPoolArgs) error {
1945		// Check if all the schedulers are disabled
1946		if len(poolArgs.EnabledSchedulers) == 0 || poolArgs.NumSchedulers == 0 {
1947			s.logger.Warn("no enabled schedulers")
1948			return nil
1949		}
1950	
1951		// Check if the core scheduler is not enabled
1952		foundCore := false
1953		for _, sched := range poolArgs.EnabledSchedulers {
1954			if sched == structs.JobTypeCore {
1955				foundCore = true
1956				continue
1957			}
1958	
1959			if _, ok := scheduler.BuiltinSchedulers[sched]; !ok {
1960				return fmt.Errorf("invalid configuration: unknown scheduler %q in enabled schedulers", sched)
1961			}
1962		}
1963		if !foundCore {
1964			return fmt.Errorf("invalid configuration: %q scheduler not enabled", structs.JobTypeCore)
1965		}
1966	
1967		s.logger.Info("starting scheduling worker(s)", "num_workers", poolArgs.NumSchedulers, "schedulers", poolArgs.EnabledSchedulers)
1968		// Start the workers
1969	
1970		for i := 0; i < s.config.NumSchedulers; i++ {
1971			if w, err := NewWorker(ctx, s, poolArgs); err != nil {
1972				return err
1973			} else {
1974				s.logger.Debug("started scheduling worker", "id", w.ID(), "index", i+1, "of", s.config.NumSchedulers)
1975				s.workerShutdownGroup.AddCh(w.ShutdownCh())
1976				s.workers = append(s.workers, w)
1977			}
1978		}
1979		s.logger.Info("started scheduling worker(s)", "num_workers", s.config.NumSchedulers, "schedulers", s.config.EnabledSchedulers)
1980		return nil
1981	}
