 456	// handleNomadConn is used to service a single Nomad RPC connection
 457	func (r *rpcHandler) handleNomadConn(ctx context.Context, conn net.Conn, server *rpc.Server) {
 458		defer conn.Close()
 459		rpcCodec := pool.NewServerCodec(conn)
 460		for {
 461			select {
 462			case <-ctx.Done():
 463				r.logger.Info("closing server RPC connection")
 464				return
 465			case <-r.srv.shutdownCh:
 466				return
 467			default:
 468			}
 469	
 470			if err := server.ServeRequest(rpcCodec); err != nil {
 471				if err != io.EOF && !strings.Contains(err.Error(), "closed") {
 472					r.logger.Error("RPC error", "error", err, "connection", conn)
 473					metrics.IncrCounter([]string{"nomad", "rpc", "request_error"}, 1)
 474				}
 475				return
 476			}
 477			metrics.IncrCounter([]string{"nomad", "rpc", "request"}, 1)
 478		}
 479	}
