 481	// handleStreamingConn is used to handle a single Streaming Nomad RPC connection.
 482	func (r *rpcHandler) handleStreamingConn(conn net.Conn) {
 483		defer conn.Close()
 484	
 485		// Decode the header
 486		var header structs.StreamingRpcHeader
 487		decoder := codec.NewDecoder(conn, structs.MsgpackHandle)
 488		if err := decoder.Decode(&header); err != nil {
 489			if err != io.EOF && !strings.Contains(err.Error(), "closed") {
 490				r.logger.Error("streaming RPC error", "error", err, "connection", conn)
 491				metrics.IncrCounter([]string{"nomad", "streaming_rpc", "request_error"}, 1)
 492			}
 493	
 494			return
 495		}
 496	
 497		ack := structs.StreamingRpcAck{}
 498		handler, err := r.srv.streamingRpcs.GetHandler(header.Method)
 499		if err != nil {
 500			r.logger.Error("streaming RPC error", "error", err, "connection", conn)
 501			metrics.IncrCounter([]string{"nomad", "streaming_rpc", "request_error"}, 1)
 502			ack.Error = err.Error()
 503		}
 504	
 505		// Send the acknowledgement
 506		encoder := codec.NewEncoder(conn, structs.MsgpackHandle)
 507		if err := encoder.Encode(ack); err != nil {
 508			conn.Close()
 509			return
 510		}
 511	
 512		if ack.Error != "" {
 513			return
 514		}
 515	
 516		// Invoke the handler
 517		metrics.IncrCounter([]string{"nomad", "streaming_rpc", "request"}, 1)
 518		handler(conn)
 519	}
